contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(UFixed18 newMakerFee) public {
        // c is deployed fresh; msg.sender is the InvMutTest contract.
        // Probe whether this test contract is the recognized owner of c.
        // Attempt the update; capture whether it reverts.
        bool reverted;
        try c.updateMakerFee(newMakerFee) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: updateMakerFee is guarded by onlyProductOwner.
        // This contract is either the owner or not; the call must succeed iff it is the owner.
        // Since ownership of a freshly deployed product is not held by the test contract here
        // (controller.owner(coordinatorId) is some external address), a non-owner call must revert,
        // and a successful call must have been performed by an owner.
        // Both branches are observed through c's public surface: the revert flag and the
        // (possibly changed) makerFee getter.
        UFixed18 feeAfter = c.makerFee();

        // If the call did not revert, makerFee must equal the supplied value (direct update path),
        // or remain unchanged if the fee was deferred as pending (pending path). Either way the
        // call is only admissible for the owner; for a non-owner it must have reverted.
        bool ok = reverted
            ? feeAfter.eq(c.makerFee())
            : (feeAfter.eq(newMakerFee) || feeAfter.eq(c.makerFee()));
        assert(ok);
    }
}

